const raw = $input.first().json.body || $input.first().json;

// 1. Identificação Básica
const nomeEmpresa = (raw.nome_empresa || raw.nome || "Novo Cliente").trim();
const nomeResponsavel = (raw.nome_responsavel || raw.responsavel || "Parceiro(a)").trim();

// 2. Normalização de Slug e ID
const slugEmpresa = nomeEmpresa
  .toLowerCase()
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .replace(/[^a-z0-9]+/g, "-")
  .replace(/(^-|-$)/g, "");

const projectId = `${slugEmpresa}-${Date.now()}`;

// 3. Sanitização de Números Telefônicos
function cleanPhone(phone) {
  if (!phone) return "";
  let digits = String(phone).replace(/\D/g, "");
  // Se começou com 0, remove
  if (digits.startsWith("0")) digits = digits.substring(1);
  // Se tem 10 ou 11 dígitos (DDD + Número), prefixa com 55 (Brasil)
  if (digits.length === 10 || digits.length === 11) {
    digits = "55" + digits;
  }
  return digits;
}

const whatsappCliente = cleanPhone(raw.whatsapp_cliente || raw.telefone || raw.phone);

let membrosAgencia = [];
if (Array.isArray(raw.membros_agencia)) {
  membrosAgencia = raw.membros_agencia.map(cleanPhone).filter(Boolean);
} else if (typeof raw.membros_agencia === "string" && raw.membros_agencia.trim()) {
  membrosAgencia = raw.membros_agencia.split(",").map(s => cleanPhone(s.trim())).filter(Boolean);
}

// Participantes para a criação do grupo no WuzAPI (Cliente + Time da Agência)
const participantesSet = new Set();
if (whatsappCliente) participantesSet.add(whatsappCliente);
membrosAgencia.forEach(p => participantesSet.add(p));
const participantes = Array.from(participantesSet);

// 4. Configurações de API e Ambiente
const urlWuzapi = raw.url_wuzapi || "https://wuzapi.inovareinteligenciaartificial.com";
const tokenWuzapi = raw.token_wuzapi || "pessoal";
const urlQnp = raw.url_qnp || "https://webhookn8n6.inovareinteligenciaartificial.com/webhook/form-qnp";
const urlVideo = raw.url_video_boas_vindas || "https://loom.com/share/cronograma-30-dias-onboarding";
const parentFolderId = raw.parent_folder_id || "";

// 5. Nomes Padronizados
const nomeGrupo = `🚀 ${nomeEmpresa} x Agência`;
const nomePastaDrive = `📁 ${nomeEmpresa} — Central de Inteligência`;

return [{
  json: {
    project_id: projectId,
    slug_empresa: slugEmpresa,
    nome_empresa: nomeEmpresa,
    nome_responsavel: nomeResponsavel,
    whatsapp_cliente: whatsappCliente,
    membros_agencia: membrosAgencia,
    participantes: participantes,
    nome_grupo: nomeGrupo,
    nome_pasta_drive: nomePastaDrive,
    parent_folder_id: parentFolderId,
    url_wuzapi: urlWuzapi,
    token_wuzapi: tokenWuzapi,
    url_qnp: urlQnp,
    url_video_boas_vindas: urlVideo,
    data_inicio: new Date().toISOString()
  }
}];

const items = $input.all();
const mainItem = $('Sanitizar Dados & Parâmetros').first().json;
const driveResult = items[0] ? items[0].json : {};

// Extrair Folder ID criado ou usar fallback
const rootFolderId = driveResult.id || driveResult.folderId || `folder-pop03-${mainItem.slug_empresa}`;
const driveUrl = driveResult.webViewLink || `https://drive.google.com/drive/folders/${rootFolderId}`;

// 4 Subpastas Oficiais do POP 03 (Protocolo do Cérebro Centralizado)
const subpastas = [
  "01_Materiais",
  "02_Criativos",
  "03_Criativos_e_Anuncios",
  "04_Relatorios_e_Dashboards"
];

return subpastas.map((nome, index) => ({
