} catch(e) {}

return [{
  json: {
    ...mainItem,
    drive_folder_url: driveFolderUrl,
    total_subpastas_criadas: subpastasResults.length
  }
}];

const input = $input.first().json;
const prevData = $('Preparar Payload WuzAPI').first().json;

// Extrai o JID retornado pelo WuzAPI (/group/create)
let groupJid = "";
if (input.JID) groupJid = input.JID;
else if (input.jid) groupJid = input.jid;
else if (input.GroupJID) groupJid = input.GroupJID;
else if (input.Details && input.Details.JID) groupJid = input.Details.JID;
else if (input.data && input.data.JID) groupJid = input.data.JID;
else if (input.id) groupJid = input.id;
else {
  // Fallback para desenvolvimento e testes
  groupJid = `120363${Date.now()}@g.us`;
}

return [{
